// Monta a janela de leitura no FUSO DA CONTA e a URL completa da Graph API.
// Backfill: preencher backfill_de/backfill_ate em ads_conta e rodar no Manual.
//
// Sem URLSearchParams e sem Intl: o sandbox do task runner do n8n não expõe
// nenhum dos dois. A data sai do $now (Luxon), que o n8n injeta no Code node.
const c  = $input.first().json;
const tz = c.timezone || 'America/Sao_Paulo';

const base      = $now.setZone(tz).startOf('day');
const hojeConta = base.toFormat('yyyy-MM-dd');
const domingo   = base.weekday === 7;           // Luxon: 1=segunda, 7=domingo
const janela    = domingo ? (c.janela_semanal || 28) : (c.janela_rolante || 7);

// Modo backfill: com backfill_de e backfill_ate preenchidos em ads_conta,
// lê exatamente esse intervalo e ignora a janela rolante.
//
// SÓ VALE EM EXECUÇÃO MANUAL. Se as colunas ficarem preenchidas por engano,
// o agendamento das 07:00 continua fazendo a janela rolante normal — em vez
// de reler o mesmo intervalo antigo todo dia e parar de trazer o de ontem.
const modo   = ($execution && $execution.mode) || 'production';
const manual = modo === 'test' || modo === 'manual';

const iso   = (v) => v ? String(v).slice(0, 10) : null;
const bfDe  = iso(c.backfill_de);
const bfAte = iso(c.backfill_ate);
const backfill = manual && !!(bfDe && bfAte);
const backfill_ignorado = !manual && !!(bfDe && bfAte);

const ate = backfill ? bfAte : base.minus({ days: 1 }).toFormat('yyyy-MM-dd');
const de  = backfill ? bfDe  : base.minus({ days: janela }).toFormat('yyyy-MM-dd');

const fields = [
  'date_start', 'ad_id', 'adset_id', 'campaign_id',
  'campaign_name', 'adset_name', 'ad_name', 'objective',
  'spend', 'impressions', 'reach', 'clicks', 'inline_link_clicks',
  'actions', 'action_values'
].join(',');

const params = [
  ['level', 'ad'],
  ['time_increment', '1'],
  ['time_range', JSON.stringify({ since: de, until: ate })],
  ['fields', fields],
  ['action_breakdowns', 'action_type'],
  ['limit', '500'],
  // SEM filtering: linha com conversão e gasto zero também entra.
];

if (c.usar_atribuicao_unificada === false) {
  params.push(['use_unified_attribution_setting', 'false']);
  params.push(['action_attribution_windows', JSON.stringify(String(c.atribuicao).split(','))]);
} else {
  params.push(['use_unified_attribution_setting', 'true']);
}

const qs = params
  .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v))
  .join('&');

const url = 'https://graph.facebook.com/v23.0/act_' + c.conta_id + '/insights?' + qs;

return [{ json: { ...c, hoje_conta: hojeConta, domingo, modo,
                  backfill, backfill_ignorado,
                  janela_dias: backfill ? null : janela, de, ate, url } }];

