// Achata as páginas da Graph API num único payload JSON.
// leads / lpv NÃO são calculados aqui: saem de fn_ads_leads() no upsert,
// para que mudar o mapa de action_type conserte o histórico sem rechamar a API.
const j = $('Janela').first().json;
const rows = [];
let paginas = 0;

for (const item of $input.all()) {
  paginas++;
  for (const r of (item.json.data ?? [])) {
    rows.push({
      dia: r.date_start,
      ad_id: String(r.ad_id),
      adset_id: r.adset_id ? String(r.adset_id) : null,
      campaign_id: r.campaign_id ? String(r.campaign_id) : null,
      conta_id: j.conta_id,
      atribuicao: j.usar_atribuicao_unificada === false ? j.atribuicao : 'unified',
      spend: Number(r.spend ?? 0),
      impressoes: Number(r.impressions ?? 0),
      alcance: Number(r.reach ?? 0),
      cliques: Number(r.clicks ?? 0),
      cliques_link: Number(r.inline_link_clicks ?? 0),
      actions_raw: r.actions ?? [],
      action_values_raw: r.action_values ?? [],
      campaign_nome: r.campaign_name ?? null,
      objetivo: r.objective ?? null,
      adset_nome: r.adset_name ?? null,
      ad_nome: r.ad_name ?? null,
    });
  }
}

return [{ json: {
  conta_id: j.conta_id,
  conta_nome: j.nome,
  de: j.de,
  ate: j.ate,
  log_id: $('Log Inicio').first().json.id,
  paginas,
  linhas: rows.length,
  payload: JSON.stringify(rows),
} }];
